class CustomStack:
    def __init__(self, maxSize: int):
        self.stack = []
        self.inc = []
        self.maxSize = maxSize

    def push(self, x: int) -> None:
        if len(self.stack) < self.maxSize:
            self.stack.append(x)
            self.inc.append(0)

    def pop(self) -> int:
        if not self.stack:
            return -1
        idx = len(self.stack) - 1
        val = self.stack.pop() + self.inc[idx]
        if idx > 0:
            self.inc[idx - 1] += self.inc[idx]
        self.inc.pop()
        return val

    def increment(self, k: int, val: int) -> None:
        if self.stack:
            idx = min(k, len(self.stack)) - 1
            self.inc[idx] += val

class Solution:
    def maxPerformance(self, n: int, speed: List[int], efficiency: List[int], k: int) -> int:
        import heapq
        engineers = sorted(zip(efficiency, speed), reverse=True)
        heap = []
        speed_sum = 0
        res = 0
        for eff, spd in engineers:
            heapq.heappush(heap, spd)
            speed_sum += spd
            if len(heap) > k:
                speed_sum -= heapq.heappop(heap)
            res = max(res, speed_sum * eff)
        return res % (10**9 + 7)

class Solution:
    def findTheDistanceValue(self, arr1: List[int], arr2: List[int], d: int) -> int:
        from bisect import bisect_left
        arr2.sort()
        res = 0
        for x in arr1:
            idx = bisect_left(arr2, x)
            valid = True
            if idx < len(arr2) and abs(arr2[idx] - x) <= d:
                valid = False
            if idx > 0 and abs(arr2[idx-1] - x) <= d:
                valid = False
            if valid:
                res += 1
        return res

class Solution:
    def maxNumberOfFamilies(self, n: int, reservedSeats: List[List[int]]) -> int:
        from collections import defaultdict
        rows = defaultdict(int)
        for r, c in reservedSeats:
            rows[r] |= 1 << c
        res = 2 * (n - len(rows))
        for mask in rows.values():
            left = not (mask & 0b0111100000)   # seats 2-5
            mid = not (mask & 0b0001111000)    # seats 4-7
            right = not (mask & 0b0000011110)  # seats 6-9
            if left and right:
                res += 2
            elif left or mid or right:
                res += 1
        return res

class Solution:
    def getKth(self, lo: int, hi: int, k: int) -> int:
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def power(n):
            if n == 1: return 0
            if n % 2 == 0: return 1 + power(n // 2)
            return 1 + power(3 * n + 1)
        nums = list(range(lo, hi + 1))
        nums.sort(key=lambda x: (power(x), x))
        return nums[k - 1]

class Solution:
    def maxSizeSlices(self, slices: List[int]) -> int:
        def maxSum(arr, k):
            n = len(arr)
            dp = [[-float('inf')] * (k + 1) for _ in range(n + 1)]
            for i in range(n + 1):
                dp[i][0] = 0
            for i in range(1, n + 1):
                for j in range(1, k + 1):
                    dp[i][j] = dp[i-1][j]
                    if i >= 2:
                        dp[i][j] = max(dp[i][j], dp[i-2][j-1] + arr[i-1])
                    else:
                        dp[i][j] = max(dp[i][j], arr[i-1])
            return dp[n][k]
        n = len(slices) // 3
        return max(maxSum(slices[1:], n), maxSum(slices[:-1], n))

