class Solution:
    def numTeams(self, rating: List[int]) -> int:
        n = len(rating)
        res = 0
        for j in range(1, n - 1):
            left_less = left_greater = 0
            right_less = right_greater = 0
            for i in range(j):
                if rating[i] < rating[j]: left_less += 1
                elif rating[i] > rating[j]: left_greater += 1
            for k in range(j + 1, n):
                if rating[k] > rating[j]: right_greater += 1
                elif rating[k] < rating[j]: right_less += 1
            res += left_less * right_greater + left_greater * right_less
        return res

class UndergroundSystem:
    def __init__(self):
        self.check_in = {}
        self.travel = {}

    def checkIn(self, id: int, stationName: str, t: int) -> None:
        self.check_in[id] = (stationName, t)

    def checkOut(self, id: int, stationName: str, t: int) -> None:
        start, start_t = self.check_in.pop(id)
        key = (start, stationName)
        if key not in self.travel:
            self.travel[key] = [0, 0]
        self.travel[key][0] += t - start_t
        self.travel[key][1] += 1

    def getAverageTime(self, startStation: str, endStation: str) -> float:
        total, count = self.travel[(startStation, endStation)]
        return total / count

class Solution:
    def countLargestGroup(self, n: int) -> int:
        from collections import Counter
        groups = Counter()
        for i in range(1, n + 1):
            digit_sum = sum(int(d) for d in str(i))
            groups[digit_sum] += 1
        max_size = max(groups.values())
        return sum(1 for v in groups.values() if v == max_size)

class Solution:
    def canConstruct(self, s: str, k: int) -> bool:
