class Solution:
    def findMinFibonacciNumbers(self, k):
        fibs = [1, 1]
        while fibs[-1] < k:
            fibs.append(fibs[-1] + fibs[-2])
        count = 0
        for f in reversed(fibs):
            if f <= k:
                k -= f
                count += 1
            if k == 0:
                break
        return count

class Solution:
    def numberOfArrays(self, s, k):
        MOD = 10**9 + 7
        n = len(s)
        dp = [0] * (n + 1)
        dp[0] = 1
        for i in range(1, n + 1):
            num = 0
            for j in range(i, 0, -1):
                num = int(s[j-1]) * (10 ** (i - j)) + num
                if num > k:
                    break
                if s[j-1] != '0':
                    dp[i] = (dp[i] + dp[j-1]) % MOD
        return dp[n]

class Solution:
    def reformat(self, s):
        letters = [c for c in s if c.isalpha()]
        digits = [c for c in s if c.isdigit()]
        if abs(len(letters) - len(digits)) > 1:
            return ""
        if len(digits) > len(letters):
            letters, digits = digits, letters
        res = []
        for i in range(len(digits)):
            res.append(letters[i])
            res.append(digits[i])
        if len(letters) > len(digits):
            res.append(letters[-1])
        return ''.join(res)

class Solution:
    def minNumberOfFrogs(self, croakOfFrogs):
        count = [0] * 5
        idx = {'c':0,'r':1,'o':2,'a':3,'k':4}
        max_frogs = 0
        for ch in croakOfFrogs:
            i = idx[ch]
            if i == 0:
                count[0] += 1
                max_frogs = max(max_frogs, count[0])
            else:
                if count[i-1] == 0:
                    return -1
                count[i-1] -= 1
                count[i] += 1
            if i == 4:
                count[4] -= 1
        return max_frogs if all(c == 0 for c in count) else -1

class Solution:
    def numOfArrays(self, n, m, k):
        MOD = 10**9 + 7
        # dp[cost][maxVal] = number of arrays of current length
        dp = [[0]*(m+1) for _ in range(k+1)]
        for v in range(1, m+1):
            dp[1][v] = 1
        for i in range(2, n+1):
            ndp = [[0]*(m+1) for _ in range(k+1)]
            for cost in range(1, k+1):
                for maxv in range(1, m+1):
                    # same max: any value 1..maxv
                    ndp[cost][maxv] = dp[cost][maxv] * maxv % MOD
                    # new max = maxv: prev max < maxv
                    for old in range(1, maxv):
                        ndp[cost][maxv] = (ndp[cost][maxv] + dp[cost-1][old]) % MOD
            dp = ndp
        return sum(dp[k]) % MOD

class Solution:
    def maxScore(self, s):
        ones = s.count('1')
        zeros = 0
        best = 0
        for i in range(len(s) - 1):
            if s[i] == '0':
                zeros += 1
            else:
                ones -= 1
            best = max(best, zeros + ones)
        return best

class Solution:
    def maxScore(self, cardPoints, k):
        n = len(cardPoints)
        window = n - k
        curr = sum(cardPoints[:window])
        min_sum = curr
        for i in range(window, n):
            curr += cardPoints[i] - cardPoints[i - window]
            min_sum = min(min_sum, curr)
        return sum(cardPoints) - min_sum

class Solution:
    def findDiagonalOrder(self, nums):
        from collections import defaultdict
        diags = defaultdict(list)
        for i, row in enumerate(nums):
            for j, val in enumerate(row):
                diags[i + j].append(val)
        res = []
        for k in sorted(diags.keys()):
            res.extend(reversed(diags[k]))
        return res

class Solution:
    def constrainedSubsetSum(self, nums, k):
        from collections import deque
        n = len(nums)
        dp = nums[:]
        dq = deque()
        for i in range(n):
            if dq:
                dp[i] = max(dp[i], dp[i] + dp[dq[0]])
            while dq and dp[dq[-1]] <= dp[i]:
                dq.pop()
            dq.append(i)
            if dq[0] <= i - k:
                dq.popleft()
        return max(dp)

