class Solution:
    def numberWays(self, hats):
        MOD = 10**9 + 7
        n = len(hats)
        hat_to_people = [[] for _ in range(41)]
        for i, h_list in enumerate(hats):
            for h in h_list:
                hat_to_people[h].append(i)
        dp = [0] * (1 << n)
        dp[0] = 1
        for h in range(1, 41):
            for mask in range((1 << n) - 1, -1, -1):
                for p in hat_to_people[h]:
                    if not (mask & (1 << p)):
                        dp[mask | (1 << p)] = (dp[mask | (1 << p)] + dp[mask]) % MOD
        return dp[(1 << n) - 1]

