class Solution:
    def longestSubarray(self, nums, limit):
        from collections import deque
        maxd, mind = deque(), deque()
        left = 0
        ans = 0
        for right, val in enumerate(nums):
            while maxd and nums[maxd[-1]] <= val:
                maxd.pop()
            while mind and nums[mind[-1]] >= val:
                mind.pop()
            maxd.append(right)
            mind.append(right)
            while nums[maxd[0]] - nums[mind[0]] > limit:
                left += 1
                if maxd[0] < left:
                    maxd.popleft()
                if mind[0] < left:
                    mind.popleft()
            ans = max(ans, right - left + 1)
        return ans

class Solution:
    def kthSmallest(self, mat, k):
        import heapq
        prev = mat[0][:k]
        for row in mat[1:]:
            heap = []
            for a in prev:
                for b in row:
                    if len(heap) < k:
                        heapq.heappush(heap, -(a + b))
                    elif -(a + b) > heap[0]:
                        heapq.heapreplace(heap, -(a + b))
                    else:
                        break
            prev = sorted([-x for x in heap])
        return prev[k-1]
